 auto verify=[&]{auto archive=project::encodeEditableProject(d);auto data=project::prepareEditableImport(project::readProjectManifest(archive.bytes));auto opened=Document::fromImported(data.width,data.height,std::move(data.timeline),d.palette(),data.id,data.name,archive.bytes);for(std::size_t i=0;i<pixels.size();++i)check(compositeNormalRegion(opened.timeline(),opened.timeline().state().frames[i].id,{0,0,5,5})==pixels[i],"styled rasterize project reopen exact");};verify();d.undo();check(d.layer().layerStyles&&d.activeMaskId()==mask&&d.timeline().state().masks.size()==1&&d.timeline().findCel(id,second)->linkedCelId,"styled rasterize undo styles masks links context");d.redo();verify();
 Document disabled(2,1);disabled.beginStroke({0,0},0xffabcdef);disabled.commitStroke();disabled.addLinkedFrame();style.enabled=false;disabled.beginLayerStyle();disabled.commitLayerStyle(style);disabled.createAttachedMask(disabled.layer().id,disabled.frame().id);const auto old=disabled.pixels();const auto link=disabled.cel().linkedCelId;check(disabled.rasterizeLayer(disabled.layer().id)&&!disabled.layer().layerStyles&&disabled.timeline().state().masks.size()==1&&disabled.cel().linkedCelId==link&&disabled.pixels()==old,"disabled configured styles clear without baking masks or links");disabled.undo();check(disabled.layer().layerStyles&&!disabled.layer().layerStyles->enabled,"disabled style undo");
